css:
table {
    margin: 0 auto; /* or margin: 0 auto 0 auto */
    width: 100%;
  }
 
.signature-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 14px;
}

.signature-line {
    width: 220px;
    border-top: 1px solid #000;
    margin-top: 0;
}
#table th, #table td {
    border: 1px solid black;
}

#main {
   margin-left: 20px;
   margin-right: 20px;
}

@media all {
   div .printedby {
       position: absolute;
       bottom: 30px;
       left: 0;
       text-align: center;
       font-size: xx-small;
       width: 100% !important;
       height: 20px !important;
   }
}
   div .terms {
	font-size: 20%;
   }

#lastPara { margin-bottom: 0; padding-bottom: 0; }
